import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class AbstractScopeBuilder_visit_TriageGen2Test {

    @Mock
    private NodeTraversal t;
    @Mock
    private Node n;
    @Mock
    private Node parent;
    @Mock
    private Node firstChild;
    @Mock
    private Node nextChild;
    @Mock
    private Node input;

    private TypedScopeCreator.AbstractScopeBuilder scopeBuilder;

    @Before
    public void setUp() {
        // Since AbstractScopeBuilder is abstract, we use a spy of a concrete implementation 
        // or a mock of the abstract class that allows us to stub the protected/internal methods.
        scopeBuilder = spy(new TypedScopeCreator.AbstractScopeBuilder() {
            @Override
            public void attachLiteralTypes(NodeTraversal t, Node n) {}
            @Override
            protected void checkForClassDefiningCalls(NodeTraversal t, Node n, Node parent) {}
            @Override
            protected void checkForCallingConventionDefiningCalls(Node n, java.util.Map<String, String> delegateCallingConventions) {}
            @Override
            protected void defineFunctionLiteral(Node n, Node parent) {}
            @Override
            protected void maybeDeclareQualifiedName(NodeTraversal t, JSDocInfo jsDocInfo, Node name, Node assignment, Node next) {}
            @Override
            protected void defineCatch(Node n, Node parent) {}
            @Override
            protected void defineVar(Node n, Node parent) {}
        });

        when(t.getInputId()).thenReturn("testId");
    }

    @Test
    public void testVisit_CallToken() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.CALL);
        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder).checkForClassDefiningCalls(eq(t), eq(n), eq(parent));
        verify(scopeBuilder).checkForCallingConventionDefiningCalls(eq(n), any());
    }

    @Test
    public void testVisit_FunctionToken_NonExtern() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.FUNCTION);
        when(t.getInput()).thenReturn(input);
        when(input.isExtern()).thenReturn(false);
        // Mock NodeUtil.isHoistedFunctionDeclaration via a static mock if possible, 
        // but since we can't easily, we assume it returns false for this test case.
        // Note: In a real environment, NodeUtil needs to be handled or shadowed.

        scopeBuilder.visit(t, n, parent);
        // Verification of nonExternFunctions.add(n) is implicit if we had access to the list
    }

    @Test
    public void testVisit_FunctionToken_Extern() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.FUNCTION);
        when(t.getInput()).thenReturn(input);
        when(input.isExtern()).thenReturn(true);

        scopeBuilder.visit(t, n, parent);
        // Should not call defineFunctionLiteral if it were hoisted, 
        // but here we focus on the extern logic.
    }

    @Test
    public void testVisit_AssignToken_QualifiedName() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.ASSIGN);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.isGetProp()).thenReturn(true);
        when(firstChild.isQualifiedName()).thenReturn(true);
        when(firstChild.getNext()).thenReturn(nextChild);

        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder).maybeDeclareQualifiedName(eq(t), any(), eq(firstChild), eq(n), eq(nextChild));
    }

    @Test
    public void testVisit_AssignToken_NotQualified() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.ASSIGN);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.isGetProp()).thenReturn(true);
        when(firstChild.isQualifiedName()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }

    @Test
    public void testVisit_CatchToken() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.CATCH);
        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder).defineCatch(n, parent);
    }

    @Test
    public void testVisit_VarToken() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.VAR);
        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder).defineVar(n, parent);
    }

    @Test
    public void testVisit_GetPropToken_QualifiedName() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.GETPROP);
        when(parent.isExprResult()).thenReturn(true);
        when(n.isQualifiedName()).thenReturn(true);

        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder).maybeDeclareQualifiedName(eq(t), any(), eq(n), eq(parent), eq(null));
    }

    @Test
    public void testVisit_GetPropToken_NotQualified() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.GETPROP);
        when(parent.isExprResult()).thenReturn(true);
        when(n.isQualifiedName()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }

    @Test
    public void testVisit_GetPropToken_NotExprResult() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.GETPROP);
        when(parent.isExprResult()).thenReturn(false);
        when(n.isQualifiedName()).thenReturn(true);

        scopeBuilder.visit(t, n, parent);
        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }
}
